import{_ as e,o as r,c as s,a2 as i}from"./chunks/framework.ChIlRNAd.js";const g=JSON.parse('{"title":"Administration","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/admin.md","filePath":"fr/guide/admin.md"}'),a={name:"fr/guide/admin.md"};function o(n,t,l,u,d,c){return r(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="administration" tabindex="-1">Administration <a class="header-anchor" href="#administration" aria-label="Permalink to &quot;Administration&quot;">​</a></h1><p>La page <strong>Admin</strong> (<code>/admin</code>) est réservée aux utilisateurs ayant le rôle <strong>admin</strong> : l&#39;entrée n&#39;apparaît que pour eux (groupe <strong>Administration</strong> de la barre latérale, ou <strong>Plus › Administration</strong> sur mobile), et l&#39;adresse renvoie les autres vers la Vue d&#39;ensemble.</p><p>Trois onglets : <strong>Utilisateurs</strong>, <strong>Système</strong>, <strong>Audit</strong>.</p><hr><h2 id="utilisateurs" tabindex="-1">Utilisateurs <a class="header-anchor" href="#utilisateurs" aria-label="Permalink to &quot;Utilisateurs&quot;">​</a></h2><p>Recherche par <strong>Email ou nom</strong>, puis la liste paginée :</p><table tabindex="0"><thead><tr><th>Colonne</th><th>Contenu</th></tr></thead><tbody><tr><td><strong>Utilisateur</strong></td><td>email et nom</td></tr><tr><td><strong>Rôle</strong></td><td>Admin ou Utilisateur</td></tr><tr><td><strong>Statut</strong></td><td>Actif ou Désactivé</td></tr><tr><td><strong>Comptes Gmail</strong></td><td>« N / max comptes »</td></tr><tr><td><strong>Stockage</strong></td><td>archives utilisées / quota</td></tr><tr><td><strong>Dernière connexion</strong></td><td>date, ou « Jamais connecté »</td></tr></tbody></table><p><strong>Modifier</strong> ouvre « Modifier l&#39;utilisateur » :</p><ul><li><strong>Rôle</strong> : Utilisateur ou Admin ;</li><li><strong>Compte actif</strong> : un compte désactivé ne peut plus se connecter (« Ce compte a été désactivé ») ;</li><li><strong>Comptes Gmail maximum</strong> ;</li><li><strong>Quota de stockage (Go)</strong>.</li></ul><p>Sous le formulaire :</p><ul><li><strong>Réinitialiser le mot de passe</strong> : définit un nouveau mot de passe (8 caractères minimum) à transmettre à l&#39;utilisateur ; ses sessions ouvertes sont déconnectées (pour votre propre mot de passe, passez par Paramètres › Sécurité) ;</li><li><strong>Supprimer l&#39;utilisateur</strong> : après confirmation, supprime définitivement le compte, ses comptes Gmail et ses archives. Indisponible sur votre propre compte (passez par <a href="./settings.html#supprimer-mon-compte">Paramètres › Données</a>) ; le dernier admin actif ne peut pas être supprimé.</li></ul><hr><h2 id="systeme" tabindex="-1">Système <a class="header-anchor" href="#systeme" aria-label="Permalink to &quot;Système&quot;">​</a></h2><p>« Réglages de l&#39;instance Nid, pour tous les utilisateurs. »</p><h3 id="corbeille-des-archives" tabindex="-1">Corbeille des archives <a class="header-anchor" href="#corbeille-des-archives" aria-label="Permalink to &quot;Corbeille des archives&quot;">​</a></h3><ul><li><strong>Durée maximale dans la corbeille</strong> : 7, 30 ou 90 jours.</li><li>Volume actuel (« N mails · taille ») et date de la prochaine purge (ou « purge automatique désactivée »).</li><li><strong>Vider la corbeille maintenant…</strong> : après confirmation (« Vider définitivement la corbeille ? »), supprime du NAS les mails de la corbeille <strong>pour tous les utilisateurs</strong>. Irréversible.</li></ul><h3 id="integrite-des-archives" tabindex="-1">Intégrité des archives <a class="header-anchor" href="#integrite-des-archives" aria-label="Permalink to &quot;Intégrité des archives&quot;">​</a></h3><p>Vérifie que les fichiers du NAS correspondent à l&#39;index : « Archives intègres », ou le nombre de fichiers manquants, corrompus et orphelins. Affiche le dernier contrôle et le nombre de mails vérifiés. « Contrôle automatique chaque jour à 3 h. » ; <strong>Lancer un contrôle</strong> en lance un tout de suite.</p><p>En cas de problème, l&#39;événement <strong>Alerte d&#39;intégrité</strong> est notifié (voir <a href="./notifications.html">Notifications</a>).</p><h3 id="quota-api-gmail" tabindex="-1">Quota API Gmail <a class="header-anchor" href="#quota-api-gmail" aria-label="Permalink to &quot;Quota API Gmail&quot;">​</a></h3><p>Consommation du projet Google de l&#39;instance, tous comptes confondus : <strong>Unités aujourd&#39;hui</strong>, <strong>Pic par utilisateur</strong> (unités par seconde / limite), <strong>Réponses 429 sur 24 h</strong>.</p><h3 id="taches-de-tous-les-utilisateurs" tabindex="-1">Tâches de tous les utilisateurs <a class="header-anchor" href="#taches-de-tous-les-utilisateurs" aria-label="Permalink to &quot;Tâches de tous les utilisateurs&quot;">​</a></h3><p>Les 20 tâches les plus récentes de l&#39;instance : <strong>Tâche</strong>, <strong>Utilisateur</strong>, <strong>Statut</strong>, <strong>Créée</strong>.</p><hr><h2 id="audit" tabindex="-1">Audit <a class="header-anchor" href="#audit" aria-label="Permalink to &quot;Audit&quot;">​</a></h2><p>Journal de l&#39;instance, filtrable par <strong>Utilisateur</strong> (email) et par <strong>Action</strong> (ou <strong>Toutes les actions</strong>). Colonnes : <strong>Date</strong>, <strong>Utilisateur</strong>, <strong>Action</strong>, <strong>Cible</strong>.</p>',26)])])}const p=e(a,[["render",o]]);export{g as __pageData,p as default};
